set-variable.value:
#[output application/java --- {
							errorCode: error.errorType.identifier,
							errorNamespace: error.errorType.namespace,
							message: error.description,
							detailedMessage: error.detailedDescription default null,
							cause: error.cause.description default null,
							causeType: error.cause.errorType.identifier default null,
							failedComponent: error.failingComponent default null,
							timestamp: now() as String {format: 'yyyy-MM-dd\'T\'HH:mm:ssXXX'}
						}]

json-logger:logger.json-logger:content:
#[output application/json
---
{
	correlationId: vars.correlationId,
	flowName: "salesforce-callback-subflow",
	step: "CALLBACK_FAILED",
	jobId: vars.jobId,
	errorDetails: {
		errorType: error.errorType.identifier default "unknown",
		message: error.description default "unknown"
	}
}]

os:store.os:value:
#[output application/java --- {
							jobId: vars.jobId,
							correlationId: vars.correlationId,
							payload: vars.callbackPayload,
							failedAt: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"},
							error: {
								'type': error.errorType.identifier default "unknown",
								message: error.description default "unknown"
							}
						}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	claimId: vars.claimId as String,
	sourceContentDocumentId: vars.contentDocumentId as String,
	sourceContentVersionId: vars.contentVersion.Id default "" as String,
	status: "FAILED",
	error: {
		errorCode: vars.errorDetails.errorCode default "UNKNOWN_ERROR",
		message: vars.errorDetails.message default "Processing failed"
	},
	correlationId: vars.correlationId as String,
	timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ssXXX"}
}

json-logger:logger.json-logger:content:
#[output application/json
---
{
	correlationId: vars.correlationId,
	flowName: "salesforce-failure-callback-subflow",
	step: "CALLBACK_FAILURE_FAILED",
	jobId: vars.jobId,
	errorDetails: {
		errorType: error.errorType.identifier default "unknown",
		message: error.description default "unknown"
	}
}]
